def check(label, actual, expected):
    status = "[OK]" if actual == expected else "[NG]"
    print(f"{status} {label}")
    if actual != expected:
        print(f"      got:      {actual}")
        print(f"      expected: {expected}")


if __name__ == "__main__":
    check('example 1', longest_unique_run('abcabcbb'), 3)
    check('example 2', longest_unique_run('bbbbb'), 1)
    check('example 3', longest_unique_run('pwwkew'), 3)
    check('empty', longest_unique_run(''), 0)
    check('dvdf', longest_unique_run('dvdf'), 3)
    check('abba', longest_unique_run('abba'), 2)
    check('space', longest_unique_run('a b a'), 3)
    check('long', longest_unique_run(''), 10)
